// Every icon on the site, in one style: the Morse pixel marks from the nav menus. The seven agents use the
// nav's own drawings; everything else is drawn on a 12x12 grid of solid ink cells and small Morse dots.
// Names match lucide-react so a file only swaps its import. Generated by gen_icons.py; colour is currentColor.
import type { CSSProperties, SVGProps } from "react";

export type IconProps = Omit<SVGProps<SVGSVGElement>, "ref"> & {
  size?: number | string;
  strokeWidth?: number | string;
  absoluteStrokeWidth?: boolean;
  color?: string;
};
export type LucideIcon = (props: IconProps) => React.JSX.Element;

function make(name: string, inner: string): LucideIcon {
  const Icon = ({ size = 24, strokeWidth: _sw, absoluteStrokeWidth: _a, color, fill: _f, stroke: _s, className, style, ...rest }: IconProps) => (
    <svg
      xmlns="http://www.w3.org/2000/svg"
      width={size}
      height={size}
      viewBox="0 0 24 24"
      className={`px-ic px-${name}${className ? " " + className : ""}`}
      style={color ? ({ color, ...style } as CSSProperties) : style}
      {...rest}
      fill="currentColor"
      dangerouslySetInnerHTML={{ __html: inner.replace(/class="st"/g, 'class="st" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="square"') }}
    />
  );
  Icon.displayName = name;
  return Icon;
}

